     2| * IVX-SENIOR-DEV-01 — GitHub Git Service
     3| *
     4| * Standalone GitHub Contents API client for the autonomous senior developer
     5| * worker. Replicates the proven commit pattern from
     6| * backend/api/ivx-developer-deploy-control.ts (runGithubCommitFile) but as a
     7| * reusable service so the worker can commit file changes without going through
     8| * the HTTP owner-gate (the owner approval is enforced at the WAITING_APPROVAL
     9| * phase of the worker state machine before this service is ever called).
    10| *
    11| * Reads credentials from process.env:
    12| *   - GITHUB_TOKEN (required)
    13| *   - GITHUB_REPO_URL or GITHUB_OWNER + GITHUB_REPO (required)
    14| *   - GITHUB_DEFAULT_BRANCH (optional, defaults to "main")
    15| */
    16|
    17|const GITHUB_API = 'https://api.github.com';
    18|const MAX_CONTENT_LENGTH = 1_500_000;
    19|
    20|export interface GithubRepoIdentity {
    21|  owner: string;
    22|  repo: string;
    23|}
    24|
    25|export interface GithubCommitResult {
    26|  ok: boolean;
    27|  commitSha: string | null;
    28|  commitUrl: string | null;
    29|  fileUrl: string | null;
    30|  mode: 'create_new_file' | 'update_existing_file';
    31|  error: string | null;
    32|}
    33|
    34|export interface GithubFileContent {
    35|  ok: boolean;
    36|  content: string | null;
    37|  sha: string | null;
    38|  error: string | null;
    39|}
    40|
    41|function readEnv(name: string): string {
    42|  return (process.env[name] ?? '').trim();
    43|}
    44|
    45|export function parseGithubRepoUrl(url: string): GithubRepoIdentity | null {
    46|  if (!url) return null;
    47|  const trimmed = url.trim();
    48|  // git@github.com:owner/repo.git
    49|  const sshMatch = trimmed.match(/git@github\.com:([^/]+)\/([^/\s]+?)(?:\.git)?$/);
    50|  if (sshMatch) return { owner: sshMatch[1], repo: sshMatch[2] };
    51|  // https://github.com/owner/repo(.git)?
    52|  const httpsMatch = trimmed.match(/https?:\/\/github\.com\/([^/]+)\/([^/\s]+?)(?:\.git)?(?:\/.*)?$/);
    53|  if (httpsMatch) return { owner: httpsMatch[1], repo: httpsMatch[2] };
    54|  // owner/repo shorthand
    55|  const shortMatch = trimmed.match(/^([^/\s]+)\/([^/\s]+)$/);
    56|  if (shortMatch) return { owner: shortMatch[1], repo: shortMatch[2] };
    57|  return null;
    58|}
    59|
    60|export function resolveGithubRepoIdentity(): GithubRepoIdentity {
    61|  const fromUrl = readEnv('GITHUB_REPO_URL');
    62|  if (fromUrl) {
    63|    const parsed = parseGithubRepoUrl(fromUrl);
    64|    if (parsed) return parsed;
    65|  }
    66|  const owner = readEnv('GITHUB_OWNER');
    67|  const repo = readEnv('GITHUB_REPO') || readEnv('GITHUB_REPOSITORY');
    68|  if (owner && repo) return { owner, repo };
    69|  const repository = readEnv('GITHUB_REPOSITORY');
    70|  if (repository && repository.includes('/')) {
    71|    const parsed = parseGithubRepoUrl(repository);
    72|    if (parsed) return parsed;
    73|  }
    74|  throw new Error(
    75|    'GITHUB_REPO_URL is missing or invalid. It was not loaded from process.env. ' +
    76|      'Expected format: https://github.com/owner/repo or git@github.com:owner/repo.git'
    77|  );
    78|}
    79|
    80|function githubToken(): string {
    81|  const token = readEnv('GITHUB_TOKEN');
    82|  if (!token) {
    83|    throw new Error('GITHUB_TOKEN is required for the senior developer worker to commit.');
    84|  }
    85|  return token;
    86|}
    87|
    88|function githubHeaders(): HeadersInit {
    89|  return {
    90|    Accept: 'application/vnd.github+json',
    91|    Authorization: `Bearer ${githubToken()}`,
    92|    'Content-Type': 'application/json',
    93|    'X-GitHub-Api-Version': '2022-11-28',
    94|  };
    95|}
    96|
    97|function sanitizeRepoPath(path: string): string {
    98|  const repoPath = path.replace(/^\/+/, '');
    99|  if (!repoPath || repoPath.includes('..') || repoPath.endsWith('/')) {
   100|    throw new Error(`Unsafe repository path: ${path}`);
   101|  }
   102|  const lower = repoPath.toLowerCase();
   103|  const blocked =
   104|    lower === '.env' ||
   105|    lower.startsWith('.env.') ||
   106|    lower.endsWith('.pem') ||
   107|    lower.endsWith('.key') ||
   108|    lower.includes('/.env') ||
   109|    lower.includes('secret') ||
   110|    lower.includes('private-key');
   111|  if (blocked && lower !== '.env.example') {
   112|    throw new Error(`Refusing to write likely secret-bearing path: ${repoPath}`);
   113|  }
   114|  return repoPath;
   115|}
   116|
   117|function encodeRepoPath(repoPath: string): string {
   118|  return repoPath.split('/').map((part) => encodeURIComponent(part)).join('/');
   119|}
   120|
   121|async function parseJsonResponse(response: Response): Promise<unknown> {
   122|  const text = await response.text();
   123|  if (!text) return null;
   124|  try {
   125|    return JSON.parse(text) as unknown;
   126|  } catch {
   127|    return { text: text.slice(0, 600) };
   128|  }
   129|}
   130|
   131|function readRecord(value: unknown): Record<string, unknown> {
   132|  return value && typeof value === 'object' && !Array.isArray(value)
   133|    ? (value as Record<string, unknown>)
   134|    : {};
   135|}
