   137|/**
   138| * Read a file from the GitHub repository (raw content, decoded).
   139| */
   140|export async function githubReadFile(repoPath: string, branch?: string): Promise<GithubFileContent> {
   141|  const repo = resolveGithubRepoIdentity();
   142|  const safePath = sanitizeRepoPath(repoPath);
   143|  const ref = branch || readEnv('GITHUB_DEFAULT_BRANCH') || 'main';
   144|  const encoded = encodeRepoPath(safePath);
   145|  const url = `${GITHUB_API}/repos/${repo.owner}/${repo.repo}/contents/${encoded}?ref=${encodeURIComponent(ref)}`;
   146|  try {
   147|    const res = await fetch(url, { headers: githubHeaders() });
   148|    if (res.status === 404) return { ok: false, content: null, sha: null, error: 'File not found.' };
   149|    if (!res.ok) return { ok: false, content: null, sha: null, error: `GitHub API ${res.status}` };
   150|    const data = readRecord(await parseJsonResponse(res));
   151|    const sha = typeof data.sha === 'string' ? data.sha : null;
   152|    const encodedContent = typeof data.content === 'string' ? data.content.replace(/\n/g, '') : '';
   153|    const content = encodedContent ? Buffer.from(encodedContent, 'base64').toString('utf8') : '';
   154|    return { ok: true, content, sha, error: null };
   155|  } catch (err) {
   156|    return { ok: false, content: null, sha: null, error: err instanceof Error ? err.message : String(err) };
   157|  }
   158|}
