   231|/**
   232| * Get the current HEAD SHA of the default branch.
   233| */
   234|export async function githubGetHeadSha(branch?: string): Promise<{ sha: string | null; error: string | null }> {
   235|  const repo = resolveGithubRepoIdentity();
   236|  const ref = branch || readEnv('GITHUB_DEFAULT_BRANCH') || 'main';
   237|  try {
   238|    const res = await fetch(`${GITHUB_API}/repos/${repo.owner}/${repo.repo}/commits/${encodeURIComponent(ref)}`, {
   239|      headers: githubHeaders(),
   240|    });
   241|    if (!res.ok) return { sha: null, error: `GitHub API ${res.status}` };
   242|    const data = readRecord(await parseJsonResponse(res));
   243|    return { sha: typeof data.sha === 'string' ? data.sha : null, error: null };
   244|  } catch (err) {
   245|    return { sha: null, error: err instanceof Error ? err.message : String(err) };
   246|  }
   247|}
