   255|/**
   256| * List the repository file tree (recursive) via the Git Trees API.
   257| * Returns source files relevant to engineering planning (filters out
   258| * node_modules, build artifacts, logs, assets, and other non-source paths
   259| * so the AI planning prompt stays within token limits and focuses on code).
   260| */
   261|export async function githubListFiles(branch?: string): Promise<GithubFileTreeResult> {
   262|  const repo = resolveGithubRepoIdentity();
   263|  const ref = branch || readEnv('GITHUB_DEFAULT_BRANCH') || 'main';
   264|  try {
   265|    const res = await fetch(`${GITHUB_API}/repos/${repo.owner}/${repo.repo}/git/trees/${encodeURIComponent(ref)}?recursive=1`, {
   266|      headers: githubHeaders(),
   267|    });
   268|    if (!res.ok) return { ok: false, files: [], error: `GitHub API ${res.status}` };
   269|    const data = readRecord(await parseJsonResponse(res));
   270|    const tree = Array.isArray(data.tree) ? (data.tree as Array<Record<string, unknown>>) : [];
   271|    const allPaths = tree
   272|      .filter((node) => node.type === 'blob' && typeof node.path === 'string')
   273|      .map((node) => node.path as string);
   274|    const files = allPaths.filter((p) => isRelevantSourcePath(p));
   275|    return { ok: true, files, error: null };
   276|  } catch (err) {
   277|    return { ok: false, files: [], error: err instanceof Error ? err.message : String(err) };
   278|  }
   279|}
