   330|
   331|function isRelevantSourcePath(path: string): boolean {
   332|  if (BLOCKED_PATH_PREFIXES.some((prefix) => path.startsWith(prefix))) return false;
   333|  if (BLOCKED_PATH_SEGMENTS.some((seg) => path.includes(seg))) return false;
